                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {\n  /** Width-to-height ratio to constrain the content to, e.g. `16 / 9`. Defaults to `1`. */\n  ratio?: number;\n}\n\n<const/{ ratio = 1, class: className, content, ...rest }=input/>\n\n<div ...rest data-slot=\"aspect-ratio\" class=cn(\"relative w-full\", className) style={ \"aspect-ratio\": String(ratio) }>\n  <div class=\"absolute inset-0\">\n    <${content}/>\n  </div>\n</div>\n"
