                      "path": "src/components/ui/breadcrumb/breadcrumb.marko",
                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"nav\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<nav ...rest aria-label=\"breadcrumb\" data-slot=\"breadcrumb\">\n  <ol data-slot=\"breadcrumb-list\" class=cn(\n    \"text-muted-foreground flex flex-wrap items-center gap-1.5 text-sm break-words sm:gap-2.5\",\n    className,\n  )>\n    <${content}/>\n  </ol>\n</nav>\n"
