                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"a\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<a ...rest data-slot=\"breadcrumb-link\" class=cn(\"hover:text-foreground transition-colors\", className)>\n  <${content}/>\n</a>\n"
