",\n    \"remixicon\": \"RiThumbDownLine\"\n  },\n  \"ThumbsUpIcon\": {\n    \"lucide\": \"ThumbsUpIcon\",\n    \"tabler\": \"IconThumbUp\",\n    \"hugeicons\": \"ThumbsUpIcon\",\n    \"phosphor\": \"ThumbsUpIcon\",\n    \"remixicon\": \"RiThumbUpLine\"\n  },\n  \"TimerIcon\": {\n    \"lucide\": \"TimerIcon\",\n    \"tabler\": \"IconClock\",\n    \"hugeicons\": \"Clock03Icon\",\n    \"phosphor\": \"TimerIcon\",\n    \"remixicon\": \"RiTimerLine\"\n  },\n  \"Trash2Icon\": {\n    \"lucide\": \"Trash2Icon\",\n    \"tabler\": \"IconTrash\",\n    \"hugeicons\": \"Delete02Icon\",\n    \"phosphor\": \"TrashIcon\",\n    \"remixicon\": \"RiDeleteBinLine\"\n  },\n  \"TrashIcon\": {\n    \"lucide\": \"TrashIcon\",\n    \"tabler\": \"IconTrash\",\n    \"hugeicons\": \"DeleteIcon\",\n    \"phosphor\": \"TrashIcon\",\n    \"remixicon\": \"RiDeleteBinLine\"\n  },\n  \"TrendingDownIcon\": {\n    \"lucide\": \"TrendingDownIcon\",\n    \"tabler\": \"IconTrendingDown\",\n    \"hugeicons\": \"ChartDownIcon\",\n    \"phosphor\": \"TrendDownIcon\",\n    \"remixicon\": \"RiArrowDownLine\"\n  },\n  \"TrendingUpIcon\": {\n    \"lucide\": \"TrendingUpIcon\",\n    \"tabler\": \"IconTrendingUp\",\n    \"hugeicons\": \"ChartUpIcon\",\n    \"phosphor\": \"TrendUpIcon\",\n    \"remixicon\": \"RiArrowUpLine\"\n  },\n  \"TriangleAlertIcon\": {\n    \"lucide\": \"TriangleAlertIcon\",\n    \"tabler\": \"IconAlertTriangle\",\n    \"hugeicons\": \"Alert02Icon\",\n    \"phosphor\": \"WarningIcon\",\n    \"remixicon\": \"RiErrorWarningLine\"\n  },\n  \"TvIcon\": {\n    \"lucide\": \"TvIcon\",\n    \"tabler\": \"IconDeviceTv\",\n    \"hugeicons\": \"Tv01Icon\",\n    \"phosphor\": \"TelevisionIcon\",\n    \"remixicon\": \"RiTvLine\"\n  },\n  \"UploadCloudIcon\": {\n    \"lucide\": \"UploadCloudIcon\",\n    \"tabler\": \"IconCloudUpload\",\n    \"hugeicons\": \"CloudUploadIcon\",\n    \"phosphor\": \"CloudArrowUpIcon\",\n    \"remixicon\": \"RiUploadCloudLine\"\n  },\n  \"UserRoundXIcon\": {\n    \"lucide\": \"UserRoundXIcon\",\n    \"tabler\": \"IconUserX\",\n    \"hugeicons\": \"UserRemove01Icon\",\n    \"phosphor\": \"UserMinusIcon\",\n    \"remixicon\": \"RiUserUnfollowLine\"\n  },\n  \"UsersIcon\": {\n    \"lucide\": \"UsersIcon\",\n    \"tabler\": \"IconUsers\",\n    \"hugeicons\": \"UserGroupIcon\",\n    \"phosphor\": \"UsersIcon\",\n    \"remixicon\": \"RiGroupLine\"\n  },\n  \"VideoIcon\": {\n    \"lucide\": \"VideoIcon\",\n    \"tabler\": \"IconVideoPlus\",\n    \"hugeicons\": \"RecordIcon\",\n    \"phosphor\": \"VideoIcon\",\n    \"remixicon\": \"RiVideoLine\"\n  },\n  \"Volume2Icon\": {\n    \"lucide\": \"Volume2Icon\",\n    \"tabler\": \"IconVolume\",\n    \"hugeicons\": \"VolumeHighIcon\",\n    \"phosphor\": \"SpeakerHighIcon\",\n    \"remixicon\": \"RiVolumeUpLine\"\n  },\n  \"VolumeOffIcon\": {\n    \"lucide\": \"VolumeOffIcon\",\n    \"tabler\": \"IconVolume\",\n    \"hugeicons\": \"VolumeOffIcon\",\n    \"phosphor\": \"SpeakerSlashIcon\",\n    \"remixicon\": \"RiVolumeMuteLine\"\n  },\n  \"VolumeX\": {\n    \"lucide\": \"VolumeX\",\n    \"tabler\": \"IconVolume\",\n    \"hugeicons\": \"VolumeOffIcon\",\n    \"phosphor\": \"SpeakerSlashIcon\",\n    \"remixicon\": \"RiVolumeMuteLine\"\n  },\n  \"WalletIcon\": {\n    \"lucide\": \"WalletIcon\",\n    \"tabler\": \"IconWallet\",\n    \"hugeicons\": \"Wallet01Icon\",\n    \"phosphor\": \"WalletIcon\",\n    \"remixicon\": \"RiWalletLine\"\n  },\n  \"ZapIcon\": {\n    \"lucide\": \"ZapIcon\",\n    \"tabler\": \"IconBolt\",\n    \"hugeicons\": \"ZapIcon\",\n    \"phosphor\": \"LightningIcon\",\n    \"remixicon\": \"RiFlashlightLine\"\n  },\n  \"ZoomInIcon\": {\n    \"lucide\": \"ZoomInIcon\",\n    \"tabler\": \"IconZoomIn\",\n    \"hugeicons\": \"ZoomInAreaIcon\",\n    \"phosphor\": \"MagnifyingGlassPlusIcon\",\n    \"remixicon\": \"RiZoomInLine\"\n  },\n  \"ZoomOutIcon\": {\n    \"lucide\": \"ZoomOutIcon\",\n    \"tabler\": \"IconZoomOut\",\n    \"hugeicons\": \"ZoomOutAreaIcon\",\n    \"phosphor\": \"MagnifyingGlassMinusIcon\",\n    \"remixicon\": \"RiSearchEyeLine\"\n  }\n}"
