                      "path": "src/components/ui/skeleton/skeleton.marko",
                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div ...rest data-slot=\"skeleton\" class=cn(\"bg-accent animate-pulse rounded-md\", className)>\n  <${content}/>\n</div>\n"
