      "skeleton-text": { demoId: "skeleton/skeleton-text", source: "import Skeleton from \"@marko-ui/registry/ui/skeleton/skeleton.marko\";\n\n<div class=\"w-[300px] space-y-2\">\n  <Skeleton class=\"h-4 w-full\"/>\n  <Skeleton class=\"h-4 w-full\"/>\n  <Skeleton class=\"h-4 w-3/4\"/>\n</div>" },
