                      "path": "src/components/ui/table/table.marko",
                      "content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {\n  content?: Marko.Body;\n}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div ...rest data-slot=\"table-container\" class=cn(\"relative w-full overflow-x-auto\", className)>\n  <table data-slot=\"table\" class=\"w-full caption-bottom text-sm\">\n    <${content}/>\n  </table>\n</div>\n"
