      "with-text": { demoId: "textarea/with-text", source: "import Textarea from \"@marko-ui/registry/ui/textarea/textarea.marko\";\nimport Label from \"@marko-ui/registry/ui/label/label.marko\";\n\n<div class=\"grid w-full gap-1.5\">\n  <Label for=\"message-2\">Your message</Label>\n  <Textarea id=\"message-2\" placeholder=\"Type your message here.\" />\n  <p class=\"text-muted-foreground text-sm\">Your message will be copied to the support team.</p>\n</div>" },
      "with-value": { demoId: "textarea/with-value", source: "import Textarea from \"@marko-ui/registry/ui/textarea/textarea.marko\";\n\n<Textarea aria-label=\"Feedback\" value=\"This is some existing feedback that a user has already typed into the textarea. It demonstrates how the field grows with field-sizing-content as content wraps across multiple lines.\" />" },
